static int touch_probe_read(FAR struct i2c_master_s *i2c, uint8_t addr,
                            uint16_t reg, FAR uint8_t *buf, uint8_t len)
{
  uint8_t regbuf[2] =
    {
      reg >> 8, reg & 0xff
    };

  struct i2c_msg_s msgv[2] =
    {
      {
        .frequency = 100000, .addr = addr, .flags = 0,
        .buffer = regbuf, .length = sizeof(regbuf)
      },
      {
        .frequency = 100000, .addr = addr, .flags = I2C_M_READ,
        .buffer = buf, .length = len
      }
    };

  return I2C_TRANSFER(i2c, msgv, 2);
}

static void touch_probe(FAR struct i2c_master_s *i2c)
{
  uint8_t buf[8];
  int ret;
  int i;
  uint8_t last = 0xff;

  static const uint8_t addrs[2] =
    {
      0x5d, 0x14
    };

  for (i = 0; i < 2; i++)
    {
      ret = touch_probe_read(i2c, addrs[i], 0x8140, buf, 8);
      syslog(LOG_ERR, "TPROBE addr=0x%02x id: ret=%d "
             "%02x %02x %02x %02x %02x %02x %02x %02x\n",
             addrs[i], ret, buf[0], buf[1], buf[2], buf[3],
             buf[4], buf[5], buf[6], buf[7]);
    }

  ret = touch_probe_read(i2c, 0x5d, 0x8136, buf, 2);
  syslog(LOG_ERR, "TPROBE fwver @8136: ret=%d %02x%02x\n",
         ret, buf[0], buf[1]);

  ret = touch_probe_read(i2c, 0x5d, 0x8046, buf, 4);
  syslog(LOG_ERR, "TPROBE modsw @8046: ret=%d %02x %02x %02x %02x\n",
         ret, buf[0], buf[1], buf[2], buf[3]);

  syslog(LOG_ERR, "TPROBE poll status @814e for 6s, touch now\n");
  for (i = 0; i < 60; i++)
    {
      ret = touch_probe_read(i2c, 0x5d, 0x814e, buf, 1);
      if (ret < 0)
        {
          syslog(LOG_ERR, "TPROBE status read ret=%d\n", ret);
          break;
        }

      if (buf[0] != last)
        {
          syslog(LOG_ERR, "TPROBE t=%dms status=%02x gpio_in=%08x\n",
                 i * 100, buf[0],
                 getreg32(0xfe004280));
          last = buf[0];
        }

      nxsig_usleep(100 * 1000);
    }

  syslog(LOG_ERR, "TPROBE done\n");
}

int vsai_logicpi_a1_touch_register(FAR const char *devpath,
                                    FAR struct i2c_master_s *i2c)
{
  int ret;

  iinfo("devpath=%s\n", devpath);

  /* Route I2C0 to GPIOA_0 (SDA) / GPIOA_1 (SCL), function 3 */

  ret = s6_gpioa_set_mux(0, 3);
  if (ret < 0)
    {
      ierr("SDA mux failed: %d\n", ret);
      return ret;
    }

  ret = s6_gpioa_set_mux(1, 3);
  if (ret < 0)
    {
      ierr("SCL mux failed: %d\n", ret);
      return ret;
    }

  touch_probe(i2c);

